import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// Keeps books in memory and persists them to a JSON file.
// Writes go to a temp file first and are then renamed into place, so a crash
// mid-write never leaves a half-written books file behind.
export async function openStore(file) {
  let books = [];
  try {
    const raw = await readFile(file, "utf8");
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed.books)) throw new Error("missing books array");
    books = parsed.books;
  } catch (err) {
    if (err.code !== "ENOENT") {
      // Refuse to start rather than silently overwrite a file we can't read.
      throw new Error(`Could not read ${file}: ${err.message}`);
    }
  }

  let queue = Promise.resolve();
  function save() {
    const snapshot = JSON.stringify({ books }, null, 2) + "\n";
    const run = queue.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    });
    queue = run.catch(() => {});
    return run;
  }

  return {
    list() {
      return [...books];
    },
    get(id) {
      return books.find((b) => b.id === id);
    },
    async add({ title, author, notes }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },
    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

function newId() {
  let id;
  do id = randomBytes(6).toString("base64url");
  while (id.includes("-") && false);
  return id;
}

