const MAX_BODY = 64 * 1024;
const LIMITS = { title: 200, author: 200, notes: 10000 };

export function createHandler(store) {
  return async function handle(req, res) {
    try {
      const url = new URL(req.url, "http://localhost");
      const path = url.pathname;

      if (req.method === "GET" && path === "/") {
        return send(res, 200, homePage(store.list(), url.searchParams.get("error")));
      }

      if (req.method === "POST" && path === "/books") {
        const form = await readForm(req);
        const input = {
          title: clean(form.get("title"), LIMITS.title),
          author: clean(form.get("author"), LIMITS.author),
          notes: clean(form.get("notes"), LIMITS.notes, true),
        };
        if (!input.title) return redirect(res, "/?error=title");
        const book = await store.add(input);
        return redirect(res, `/books/${book.id}`);
      }

      const bookMatch = path.match(/^\/books\/([A-Za-z0-9_-]+)$/);
      if (req.method === "GET" && bookMatch) {
        const book = store.get(bookMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        return send(res, 200, bookPage(book));
      }

      const finishMatch = path.match(/^\/books\/([A-Za-z0-9_-]+)\/finish$/);
      if (req.method === "POST" && finishMatch) {
        const book = await store.finish(finishMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        const back = (await readForm(req)).get("back") === "book" ? `/books/${book.id}` : "/";
        return redirect(res, back);
      }

      return send(res, 404, notFoundPage());
    } catch (err) {
      if (err.status === 413) return send(res, 413, layout("Too large", "<p>That was too much text.</p>"));
      console.error(err);
      return send(res, 500, layout("Error", "<p>Something went wrong. Please try again.</p>"));
    }
  };
}

// ---------- pages ----------

function homePage(books, error) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt || "").localeCompare(a.finishedAt || ""));

  const list = (items, empty, withFinish) =>
    items.length === 0
      ? `<p class="empty">${empty}</p>`
      : `<ul class="books">${items.map((b) => bookRow(b, withFinish)).join("")}</ul>`;

  return layout(
    "My books",
    `
    <h1>My books</h1>
    <section>
      <h2>Currently reading</h2>
      ${list(reading, "Nothing on the go right now.", true)}
    </section>
    <section>
      <h2>Finished</h2>
      ${list(finished, "No finished books yet.", false)}
    </section>
    <section>
      <h2>Add a book</h2>
      ${error === "title" ? `<p class="error">Please give the book a title.</p>` : ""}
      <form method="post" action="/books" class="add">
        <label>Title <input name="title" required maxlength="${LIMITS.title}"></label>
        <label>Author <input name="author" maxlength="${LIMITS.author}"></label>
        <label>Notes <textarea name="notes" rows="4" maxlength="${LIMITS.notes}"></textarea></label>
        <button type="submit">Add book</button>
      </form>
    </section>`
  );
}

function bookRow(book, withFinish) {
  const finish = withFinish
    ? `<form method="post" action="/books/${book.id}/finish" class="inline">
         <button type="submit">Mark finished</button>
       </form>`
    : `<span class="meta">${formatDate(book.finishedAt)}</span>`;
  return `<li>
    <a href="/books/${book.id}">${esc(book.title)}</a>
    ${book.author ? `<span class="by">by ${esc(book.author)}</span>` : ""}
    ${finish}
  </li>`;
}

function bookPage(book) {
  const status =
    book.status === "finished"
      ? `<p class="meta">Finished ${formatDate(book.finishedAt)}</p>`
      : `<p class="meta">Currently reading</p>
         <form method="post" action="/books/${book.id}/finish">
           <input type="hidden" name="back" value="book">
           <button type="submit">Mark finished</button>
         </form>`;
  return layout(
    book.title,
    `
    <p><a href="/">&larr; All books</a></p>
    <h1>${esc(book.title)}</h1>
    <p class="author">${book.author ? `by ${esc(book.author)}` : "Unknown author"}</p>
    ${status}
    <h2>Notes</h2>
    ${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : `<p class="empty">No notes.</p>`}
    <p class="share">To share this book, send the link in your address bar.</p>`
  );
}

function notFoundPage() {
  return layout("Not found", `<h1>Not found</h1><p>That book doesn't exist.</p><p><a href="/">Back to all books</a></p>`);
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 { margin-bottom: .25rem; }
  h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: .25rem; }
  a { color: #1a5fb4; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; gap: .5rem; align-items: baseline; flex-wrap: wrap; padding: .4rem 0; border-bottom: 1px solid #f0f0f0; }
  .by, .meta, .empty, .share { color: #666; }
  .inline, .meta:last-child { margin-left: auto; }
  form.add { display: grid; gap: .75rem; }
  form.add label { display: grid; gap: .25rem; }
  input, textarea, button { font: inherit; padding: .4rem; }
  button { cursor: pointer; }
  .notes { white-space: pre-wrap; background: #fafafa; border: 1px solid #eee; padding: .75rem; }
  .error { color: #b00020; }
  .author { margin-top: 0; font-size: 1.1rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

// ---------- helpers ----------

function send(res, status, html) {
  res.writeHead(status, {
    "Content-Type": "text/html; charset=utf-8",
    "Content-Security-Policy": "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'",
    "X-Content-Type-Options": "nosniff",
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  let body = "";
  for await (const chunk of req) {
    body += chunk;
    if (body.length > MAX_BODY) {
      const err = new Error("body too large");
      err.status = 413;
      throw err;
    }
  }
  return new URLSearchParams(body);
}

function clean(value, max, multiline = false) {
  let s = (value ?? "").replace(/\r\n/g, "\n");
  s = multiline ? s.trim() : s.replace(/\s+/g, " ").trim();
  return s.slice(0, max);
}

function esc(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatDate(iso) {
  if (!iso) return "";
  return new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
}

