import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, rm, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { openStore } from "../src/store.js";
import { createHandler } from "../src/app.js";

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(createHandler(store));
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
}
async function stop() {
  await new Promise((r) => server.close(r));
}
const post = (path, fields) =>
  fetch(base + path, { method: "POST", body: new URLSearchParams(fields), redirect: "manual" });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("adds a book and links to its own page", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice.\nSand." });
    expect(res.status).toBe(303);
    const loc = res.headers.get("location");
    expect(loc).toMatch(/^\/books\/[A-Za-z0-9_-]+$/);

    const page = await (await fetch(base + loc)).text();
    expect(page).toContain("Dune");
    expect(page).toContain("by Frank Herbert");
    expect(page).toContain("Spice.\nSand.");

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).toContain("Dune");
    expect(finished.split("<h2>Add a book</h2>")[0]).not.toContain("Dune");
  });

  it("marks a book finished", async () => {
    const loc = (await post("/books", { title: "Emma" })).headers.get("location");
    const res = await post(`${loc}/finish`, {});
    expect(res.status).toBe(303);
    const home = await (await fetch(base + "/")).text();
    const finished = home.split("<h2>Finished</h2>")[1].split("<h2>Add a book</h2>")[0];
    expect(finished).toContain("Emma");
    expect(await (await fetch(base + loc)).text()).toContain("Finished");
  });

  it("keeps books across a restart", async () => {
    const loc = (await post("/books", { title: "Persist me" })).headers.get("location");
    await stop();
    await start();
    expect((await fetch(base + loc)).status).toBe(200);
    expect(JSON.parse(await readFile(file, "utf8")).books).toHaveLength(1);
  });

  it("rejects a missing title and escapes HTML", async () => {
    const bad = await post("/books", { title: "   " });
    expect(bad.headers.get("location")).toBe("/?error=title");

    const loc = (await post("/books", { title: "<script>alert(1)</script>" })).headers.get("location");
    const page = await (await fetch(base + loc)).text();
    expect(page).not.toContain("<script>alert(1)");
    expect(page).toContain("&lt;script&gt;");
  });

  it("returns 404 for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish", {})).status).toBe(404);
  });

  it("refuses to start on a corrupt data file instead of wiping it", async () => {
    await writeFile(file, "{not json");
    await expect(openStore(file)).rejects.toThrow(/Could not read/);
    expect(await readFile(file, "utf8")).toBe("{not json");
  });
});

